def seed_themed_questions():
    """Seed the themed YDKJ pack. Additive + idempotent."""
    ph = get_placeholder()
    added = 0
    skipped = 0
    for q in THEMED_QUESTIONS:
        cat = get_category_by_name(q['category'])
        if not cat:
            print(f"[themed] category '{q['category']}' missing, skipping")
            skipped += 1
            continue
        try:
            execute_query(f'''
                INSERT OR IGNORE INTO trivia_questions
                (category_id, question_text, setup_text, answer_a, answer_b, answer_c, answer_d,
                 correct_answer, difficulty, time_limit, explanation,
                 host_commentary_correct, host_commentary_wrong)
                VALUES ({ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph}, {ph})
            ''', (
                cat['id'],
                q['question'],
                q.get('setup', '') or '',
                q['answers']['A'],
                q['answers']['B'],
                q['answers']['C'],
                q['answers']['D'],
                q['correct'],
                q.get('difficulty', 'medium'),
                q.get('time_limit', 15),
                q.get('explanation', ''),
                q.get('commentary_correct', ''),
                q.get('commentary_wrong', ''),
            ))
            added += 1
        except Exception as e:
            print(f"[themed] insert error: {e}")
    print(f"✅ Themed seeder added {added} new questions ({skipped} skipped due to missing categories)")


if __name__ == '__main__':
    seed_themed_questions()
